      ['aserradero', 'mina', 'cantera', 'academia', 'almacen', 'mercado', 'herreria', 'establo', 'galeria', 'vigia', 'cabana'].forEach(function (t) { var m = crearModelo(t, 1); m.rotation.y = 0.5; retratos[t] = t === 'cabana' ? foto(m, 9, 1.6) : foto(m, 5.5, 0.9); });
