    if (t.alcance) r.push([T('alcance'), '+' + (t.alcance * L).toFixed(1)]);
    if (t.vida) r.push([T('hv_vida_heroe'), '+' + Math.round(t.vida * L * 100) + '%']);
    if (t.recarga) r.push([T('hv_recarga'), '-' + Math.round(t.recarga * L * 100) + '%']);
