          (hecho ? '<button class="iv-boton" disabled>' + L('Listo', 'Done') + '</button>' : listo ? '<button class="az-b verde pr-b" data-accion="finde-reclamar" data-i="' + i + '">' + L('Reclamar', 'Claim') + '</button>' : '') + '</div>';
