    var falta = (estado.ultSoporte || 0) + 120000 - Date.now();
    if (falta > 0) { $('sp-error').textContent = L('Espera ', 'Wait ') + fmtTiempo(falta / 1000) + L(' para mandar otro mensaje.', ' to send another message.'); sonar('error'); return; }
    b.disabled = true;
