          var usdC = +c.usd || (window.Pagos && Pagos.CATALOGO && c.sku && Pagos.CATALOGO[c.sku] ? +Pagos.CATALOGO[c.sku].usd : 0) || 0; // v8.19: +100 VIP por cada US$ 1
