      var h = 1.3 + ((i * 7919) % 5) * 0.08, e = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.18, h, 6), madera); e.position.set(0, h / 2, i * 0.72); e.rotation.x = 0.28; e.castShadow = true; g.add(e);
